def give_spots(apps, schema_editor):
    """Pokémon already at work get the spots 0, 1, 2... in the order they were shown."""
    OwnedPokemon = apps.get_model("ranch", "OwnedPokemon")
    workers = OwnedPokemon.objects.filter(zone__isnull=False).order_by("zone", "species__number")
    current_zone, spot = None, 0
    for pokemon in workers:
        spot = spot + 1 if pokemon.zone_id == current_zone else 0
        current_zone = pokemon.zone_id
        pokemon.spot = spot
        pokemon.save(update_fields=["spot"])


